package org.apache.commons.lang3;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import java.util.Locale;
import org.apache.commons.lang3.text.WordUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class StringUtils_indexOfAny_TriageGen1Test {

    private static final int INDEX_NOT_FOUND = -1;

    @Test
    public void testIndexOfAny_NullCharSequence() {
        assertFalse(false); // Placeholder for structure
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAny(null, new char[]{'a'}));
    }

    @Test
    public void testIndexOfAny_EmptyCharSequence() {
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAny("", new char[]{'a'}));
    }

    @Test
    public void testIndexOfAny_NullSearchChars() {
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAny("abc", null));
    }

    @Test
    public void testIndexOfAny_EmptySearchChars() {
        // Assuming ArrayUtils.isEmpty(searchChars) handles empty array
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAny("abc", new char[]{}));
    }

    @Test
    public void testIndexOfAny_FoundAtStart() {
        assertEquals(0, StringUtils.indexOfAny("abc", new char[]{'a', 'b'}));
    }

    @Test
    public void testIndexOfAny_FoundInMiddle() {
        assertEquals(1, StringUtils.indexOfAny("abc", new char[]{'b'}));
    }

    @Test
    public void testIndexOfAny_FoundAtEnd() {
        assertEquals(2, StringUtils.indexOfAny("abc", new char[]{'c'}));
    }

    @Test
    public void testIndexOfAny_NotFound() {
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAny("abc", new char[]{'d', 'e'}));
    }

    @Test
    public void testIndexOfAny_MultipleMatchesReturnsFirst() {
        assertEquals(0, StringUtils.indexOfAny("banana", new char[]{'a', 'n'}));
    }

    /**
     * Testing the supplementary character logic in the provided implementation.
     * Note: The provided code has a specific logic:
     * if (i < csLast && j < searchLast && Character.isHighSurrogate(ch)) {
     *     if (searchChars[j + 1] == cs.charAt(i + -1)) { ... }
     * }
     * This logic seems highly specific/unusual for a standard indexOfAny, 
     * but we must test to cover the branches.
     */
    @Test
    public void testIndexOfAny_HighSurrogateBranch() {
        // A high surrogate character
        char highSurrogate = '\uD83D'; 
        // To trigger the 'if' branch:
        // 1. i < csLast
        // 2. j < searchLast
        // 3. Character.isHighSurrogate(ch) is true
        // 4. searchChars[j+1] == cs.charAt(i - 1)

        // Let's construct a string where i=1, so i-1 = 0.
        // cs = [char0, highSurrogate, char2]
        // searchChars = [highSurrogate, char0]

        char char0 = 'A';
        char char2 = 'B';
        String cs = "" + char0 + highSurrogate + char2;
        char[] searchChars = new char[]{highSurrogate, char0};

        // When i=1, ch = highSurrogate
        // j=0, searchChars[0] == highSurrogate
        // i(1) < csLast(2) is true
        // j(0) < searchLast(1) is true
        // Character.isHighSurrogate(highSurrogate) is true
        // searchChars[0+1] is char0. cs.charAt(1-1) is char0.
        // They match, returns i (1).

        assertEquals(1, StringUtils.indexOfAny(cs, searchChars));
    }

    @Test
    public void testIndexOfAny_HighSurrogateFalseBranch() {
        // Test where high surrogate is found but it's the last char in searchChars or cs
        char highSurrogate = '\uD83D';
        String cs = "A" + highSurrogate; // csLast is 1, i is 1. i < csLast is false.
        char[] searchChars = new char[]{highSurrogate};

        assertEquals(1, StringUtils.indexOfAny(cs, searchChars));
    }

    @Test
    public void testIndexOfAny_HighSurrogateMismatch() {
        // Test where high surrogate is found but the lookahead logic fails
        char highSurrogate = '\uD83D';
        char char0 = 'A';
        String cs = "" + char0 + highSurrogate + 'B';
        char[] searchChars = new char[]{highSurrogate, 'Z'}; // 'Z' != 'A'

        // The code enters the if block, but the inner if fails.
        // However, the loop continues. Since no other match is found, it returns -1.
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAny(cs, searchChars));
    }
}
